/**
 * Publish the human-friendly /sitemap.xml using the sitemap shards generated by
 * @astrojs/sitemap. Reads build output rather than maintaining a second URL
 * registry; new 28-pair, bank, learning and other static routes automatically
 * join the sitemap on every build.
 *
 * Keeps /sitemap-index.xml and /sitemap-0.xml intact for existing consumers.
 * Does not synthesize <lastmod>: build time is not a content modification date.
 */
import { readFileSync, writeFileSync, existsSync } from "node:fs";
import { join } from "node:path";

const root = new URL("../dist/", import.meta.url);
const origin = "https://tradeninety.com";
const indexPath = new URL("sitemap-index.xml", root);
if (!existsSync(indexPath)) throw new Error("Astro sitemap index was not generated");
const indexXml = readFileSync(indexPath, "utf8");
const sitemapLocations = [...indexXml.matchAll(/<loc>\s*([^<]+)\s*<\/loc>/g)].map(match => match[1].trim());
if (!sitemapLocations.length) throw new Error("No child sitemaps in generated sitemap index");

const entries = [];
for (const href of sitemapLocations) {
  const url = new URL(href);
  if (url.origin !== origin || !/^\/sitemap-\d+\.xml$/.test(url.pathname)) {
    throw new Error("Unexpected sitemap index entry: " + href);
  }
  const file = new URL(url.pathname.slice(1), root);
  if (!existsSync(file)) throw new Error("Missing generated child sitemap: " + url.pathname);
  const xml = readFileSync(file, "utf8");
  const urls = [...xml.matchAll(/<url(?:\s[^>]*)?>[\s\S]*?<\/url>/g)].map(match => match[0]);
  if (!urls.length) throw new Error("Empty child sitemap: " + url.pathname);
  entries.push(...urls);
}
const seen = new Set();
for (const item of entries) {
  const match = item.match(/<loc>\s*([^<]+)\s*<\/loc>/);
  if (!match) throw new Error("Missing canonical loc in generated URL entry");
  const loc = match[1].trim();
  const url = new URL(loc);
  if (url.origin !== origin) throw new Error("Unexpected external sitemap URL: " + loc);
  if (url.search || url.hash) throw new Error("Query/fragment in canonical sitemap URL: " + loc);
  if (/^\/(?:404\/?|calculator\/|tools\/|research\/)/i.test(url.pathname)) {
    throw new Error("Retired or nonindexable page in sitemap: " + loc);
  }
  if (seen.has(loc)) throw new Error("Duplicate canonical sitemap URL: " + loc);
  seen.add(loc);
}
const required = ["/", "/rate-gaps/", "/pairs/", "/decisions/", "/central-banks/",
  "/learn/", "/methodology/", "/data-policy/"];
for (const pathname of required) {
  if (!seen.has(origin + pathname)) throw new Error("Required page missing from sitemap: " + pathname);
}
const expectedPairs = 28;
const expectedBanks = 8;
const pairCount = [...seen].filter(u => /\/pairs\/[a-z]{3}-[a-z]{3}\/$/.test(u)).length;
const bankCount = [...seen].filter(u => /\/central-banks\/(?:fed|ecb|boe|boj|rba|rbnz|boc|snb)\/$/.test(u)).length;
if (pairCount !== expectedPairs || bankCount !== expectedBanks) {
  throw new Error("Incomplete research pages: " + pairCount + " pairs, " + bankCount + " bank hubs");
}
const sitemap = [
  '<?xml version="1.0" encoding="UTF-8"?>',
  '<urlset xmlns="http://www.sitemaps.org/schemas/sitemap/0.9">',
  ...entries,
  '</urlset>',
  ""
].join("\n");
writeFileSync(new URL("sitemap.xml", root), sitemap, "utf8");
console.log("Published dist/sitemap.xml: " + entries.length +
  " canonical URLs (" + pairCount + " pair pages and " + bankCount + " bank hubs); " +
  sitemapLocations.length + " Astro sitemap shard(s) retained.");
